  }
  function updateBot(p,dt,i){
    const ball=match.ball,owner=ball.owner;
    let tx,ty;
    if(owner&&owner.team===1){tx=W-160;ty=H/2+(i-1.5)*55;}
    else if(owner&&owner.team===0){tx=owner.x+13;ty=owner.y+12;}

